# Lições de aprofundamento (10–22): telefonemas e mensagens em situações concretas.

L(10, "O menu automático", "Toets 1 voor … Blijf aan de lijn.",
  ["Compreender menus telefónicos automáticos e filas de espera"],
  vocab=[V("v-keuzemenu","keuzemenu","menu de opções","noun","het"), V("v-wachtrij","wachtrij","fila de espera","noun","de"),
         V("v-aan-de-lijn-blijven","aan de lijn blijven","manter-se em linha","expression"), V("v-intoetsen","intoetsen","marcar|digitar (no teclado)","verb")],
  ex=[("Kies een optie uit het keuzemenu.","Escolha uma opção do menu."),("U staat in de wachtrij.","Está em fila de espera."),("Blijft u aan de lijn.","Mantenha-se em linha."),("Toets uw klantnummer in.","Digite o seu número de cliente.")],
  review=["v-toets","v-verbinding"],
  cefr=C, exs=[
    MA([("keuzemenu","menu de opções"),("wachtrij","fila de espera"),("aan de lijn blijven","manter-se em linha"),("intoetsen","digitar")], "Menus telefónicos.", ["v-keuzemenu","v-wachtrij","v-aan-de-lijn-blijven","v-intoetsen"]),
    LI("Voor vragen over uw factuur, toets 1. Voor storingen, toets 2.", ["Voor vragen over uw factuur, toets 1. Voor storingen, toets 2","Voor vragen over uw factuur toets 1 voor storingen toets 2"], "Para perguntas sobre a fatura, marque 1. Para avarias, marque 2.", "Menu típico.", ["v-keuzemenu"]),
    MC("Ouve: «Er zijn nog vier wachtenden voor u.» O que significa?", ["*Há quatro pessoas à sua frente na fila","Tem de esperar quatro minutos|Não diz minutos.","Ligue daqui a quatro horas|Não."], "wachtenden = pessoas em espera.", ["v-wachtrij"]),
    AR("keuzemenu","o menu de opções","het", "Het menu.", ["v-keuzemenu"]),
    TR("pt-nl","Digite o seu número de cliente.", ["Toets uw klantnummer in","Toets je klantnummer in"], "intoetsen (separável).", ["v-intoetsen"]),
    TR("nl-pt","U staat in de wachtrij.", ["Está em fila de espera","Está na fila de espera"], "wachtrij.", ["v-wachtrij"]),
    CO("text","Een keuzemenu", "Welkom bij Energiebedrijf Noord. Dit gesprek kan worden opgenomen voor trainingsdoeleinden. Bent u al klant, toets dan 1. Wilt u klant worden, toets 2. Heeft u een storing, toets 3. Voor alle andere vragen, blijft u aan de lijn. Er zijn op dit moment veel bellers; u kunt ook chatten via onze website.",
       [("Para que pode ser gravada a chamada?", ["*Para formação","Para a polícia","Para publicidade"]),("Tem uma avaria. Que tecla marca?", ["*3","1","2"]),("Que alternativa sugerem?", ["*O chat no site","Uma carta","Ir à loja"])],
       "Compreender um menu.", ["v-keuzemenu","v-aan-de-lijn-blijven"]),
    CJ("intoetsen","ik","Ik heb mijn klantnummer al ___.", ["ingetoetst"], "in-ge-toetst.", ["v-intoetsen"], tense="passado-perfeito"),
    FE(["Blijf","u","op","de","lijn."], 2, "aan", "aan de lijn blijven.", ["v-aan-de-lijn-blijven"]),
    WO("Mantenha-se em linha.", ["Blijft","u","aan","de","lijn"], "Imperativo formal.", ["v-aan-de-lijn-blijven"]),
  ], diff=3, mins=6)

