    DL([("Beller","Is mevrouw Visser aanwezig?","A Sra. Visser está?"),("Receptie","","")], ["*Ze is op dit moment in gesprek. Kan ik een bericht aannemen?","Nee.|Pouco útil.","Ze spreekt.|Incompleto."], "Oferecer anotar recado.", ["v-in-gesprek","v-een-bericht-aannemen"]),
