    TR("nl-pt","We beginnen om negen uur i.p.v. tien uur.", ["Começamos às nove em vez das dez","Começamos às nove horas em vez das dez"], "i.p.v. = in plaats van.", ["v-ipv"]),
    CO("text","Mail van de school", "Beste ouders,\nM.b.t. de excursie van vrijdag: de bus vertrekt om 8.30 uur i.p.v. 9.00 uur. Geef uw kind a.u.b. een lunchpakket en een regenjas mee. Is uw kind ziek? Meld dit z.s.m. bij de administratie.\nMet vriendelijke groet,\nDe leerkracht van groep 6",
       [("A que horas parte o autocarro?", ["*8h30","9h00","10h00"]),("O que deve levar a criança?", ["*Lanche e impermeável","Dinheiro","Nada"]),("Se a criança estiver doente?", ["*Avisar a secretaria o mais depressa possível","Mandá-la na mesma","Ligar à professora no dia seguinte"])],
       "Ler um e-mail com abreviaturas.", ["v-mbt","v-ipv","v-aub","v-zsm"]),
    FB("Wilt u ___ reageren vóór vrijdag?", ["a.u.b."], "Por favor.", ["v-aub"], choices=["a.u.b.","i.p.v.","m.b.t."], tr="Pode responder, por favor, antes de sexta?"),
    FE(["Wij","komen","zaterdag","m.b.t.","zondag."], 3, "i.p.v.", "Em vez de = i.p.v.", ["v-ipv"]),
    LI("Met betrekking tot uw vraag kan ik het volgende zeggen.", ["Met betrekking tot uw vraag kan ik het volgende zeggen"], "Relativamente à sua pergunta, posso dizer o seguinte.", "Forma completa de m.b.t.", ["v-mbt"]),
    WO("Responda o mais depressa possível.", ["Reageer","z.s.m."], "Imperativo curto.", ["v-zsm"]),
