  ex=[("Hé, ik bel even over vrijdag.","Olha, estou a ligar por causa de sexta."),("Stoor ik?","Estou a incomodar?"),("Ik moet ophangen, mijn trein komt.","Tenho de desligar, vem o meu comboio."),("Oké, spreek je!","Ok, falamos!")],
  review=["v-storen","v-ophangen"],
